// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type NewsHeadlineProps = Record<string, any>;

const NewsHeadline: React.FC<NewsHeadlineProps> = ({
  backgroundColor = "#06070a",
  transparentBackground = false,
  durationInSeconds = 8,
  logoTextPart1 = "yahoo!",
  logoColorPart1 = "#7E1FFF",
  logoTextPart2 = "finance",
  logoColorPart2 = "#FFFFFF",
  headline = "Nvidia to License Groq Technology in $20 Billion AI Chip Deal",
  authorName = "Faizan Farooque",
  metaData = "December 26, 2025 • 1 min read",
  primaryTextColor = "#F8F9FA",
  secondaryTextColor = "#A0A5B0",
  enableGlow = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Handle transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Visual Effects
  const textShadow = enableGlow
    ? "0 0 10px rgba(255,255,255,0.1), -1px 0 2px rgba(126, 31, 255, 0.4), 1px 0 2px rgba(0, 255, 255, 0.4)"
    : "none";

  // Global Scale (Slow push in for dramatic effect)
  const globalScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [1, 1.05],
    { extrapolateRight: "clamp" }
  );

  // Logo Animation
  const logoDelay = 5;
  const logoProgress = spring({
    frame: frame - logoDelay,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const logoY = interpolate(logoProgress, [0, 1], [20, 0]);
  const logoOpacity = interpolate(frame, [logoDelay, logoDelay + 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Headline Words Calculation
  const words = headline.split(" ");
  const wordBaseDelay = 15;

  // Meta Data Animation
  const metaDelay = wordBaseDelay + words.length * 2 + 10;
  const metaProgress = spring({
    frame: frame - metaDelay,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const metaY = interpolate(metaProgress, [0, 1], [20, 0]);
  const metaOpacity = interpolate(frame, [metaDelay, metaDelay + 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
      }}
    >
      <AbsoluteFill
        style={{
          transform: `scale(${globalScale})`,
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            width: width * 0.65, // Limit width for typography readability
            gap: "40px",
            transition: "none",
          }}
        >
          {/* Logo Container */}
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              width: "100%",
              opacity: logoOpacity,
              transform: `translateY(${logoY}px)`,
              transition: "none",
            }}
          >
            <span
              style={{
                color: logoColorPart1,
                fontWeight: 900,
                fontStyle: "italic",
                fontSize: 48,
                letterSpacing: "-1.5px",
                transition: "none",
              }}
            >
              {logoTextPart1}
            </span>
            <span
              style={{
                color: logoColorPart2,
                fontWeight: 900,
                fontStyle: "italic",
                fontSize: 48,
                letterSpacing: "-1px",
                transition: "none",
              }}
            >
              {logoTextPart2}
            </span>
          </div>

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "24px",
              transition: "none",
            }}
          >
            {/* Headline */}
            <div
              style={{
                display: "flex",
                flexWrap: "wrap",
                columnGap: "0.28em",
                rowGap: "0.1em",
                fontSize: 64,
                fontWeight: 700,
                color: primaryTextColor,
                lineHeight: 1.25,
                letterSpacing: "-0.5px",
                textShadow: textShadow,
                transition: "none",
              }}
            >
              {words.map((word, i) => {
                const wDelay = wordBaseDelay + i * 2;
                const wProgress = spring({
                  frame: frame - wDelay,
                  fps,
                  config: { damping: 14, mass: 0.8 },
                });
                const wY = interpolate(wProgress, [0, 1], [25, 0]);
                const wOp = interpolate(
                  frame,
                  [wDelay, wDelay + 10],
                  [0, 1],
                  { extrapolateRight: "clamp" }
                );
                return (
                  <span
                    key={i}
                    style={{
                      display: "inline-block",
                      opacity: wOp,
                      transform: `translateY(${wY}px)`,
                      transition: "none",
                    }}
                  >
                    {word}
                  </span>
                );
              })}
            </div>

            {/* Meta Data */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "8px",
                color: secondaryTextColor,
                fontSize: 22,
                fontWeight: 500,
                opacity: metaOpacity,
                transform: `translateY(${metaY}px)`,
                transition: "none",
              }}
            >
              <span style={{ color: primaryTextColor, transition: "none" }}>
                {authorName}
              </span>
              <span style={{ fontSize: 20, transition: "none" }}>
                {metaData}
              </span>
            </div>
          </div>
        </div>
      </AbsoluteFill>

      {/* Overlays (Vignette & Scanlines for authentic monitor look) */}
      {!transparentBackground && (
        <>
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "100%",
              pointerEvents: "none",
              background:
                "radial-gradient(circle at center, transparent 40%, rgba(0,0,0,0.6) 100%)",
              transition: "none",
            }}
          />
          {enableGlow && (
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                pointerEvents: "none",
                background:
                  "linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.1) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.03), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.03))",
                backgroundSize: "100% 4px, 6px 100%",
                opacity: 0.5,
                transition: "none",
              }}
            />
          )}
        </>
      )}
    </AbsoluteFill>
  );
};

export default NewsHeadline;